def summe(n):
    if n == 0:
        return 0
    return n + summe(n - 1)

print(summe(4))

def f(n):
    if n == 0:
        return
    f(n - 1)
    print(n, end=" ")

f(3)

def fak(n):
    if n == 1:
        return 1
    return n * fak(n - 1)

print(fak(0))
